    requiredIngredients: [getIng('biber'), getIng('domates'), getIng('fistik'), getIng('havuc'), getIng('karabiber'), getIng('limon'), getIng('patates'), getIng('pirinc'), getIng('salca'), getIng('siviyag'), getIng('sogan'), getIng('tavuk'), getIng('tereyagi'), getIng('tuz'), getIng('un'), getIng('yogurt')],
    steps: [
        "1. Öncelikle iç pilavını hazırlamak için pilavlık pirinçler bir kaba alınır.",
        "2. Üzerini geçecek kadar ılık su ve tuz eklenerek 20 dakika bekletilir. Daha sonra bol su ile yıkanarak pişirme aşamasına geçilir.",
        "3. Pilavı pişirmek için öncelikle pilav tenceresine tereyağı ve sıvı yağ alınır. Ben tereyağı ve sıvı yağı karışık kullanıyorum, çünkü hem tereyağının lezzetini seviyorum, hem de sıvı yağın parlaklık verdiğini düşünüyorum.",
