  Recipe(
    id: "r_44",
    title: "İzmir Bombası",
    emoji: "🧁",
    imageUrl: "https://i.nefisyemektarifleri.com/2023/04/07/izmir-bombasi-kolay-ve-az-malzemeli.jpg",
    imageAsset: "assets/images/044.webp",
    prepTimeMinutes: 16,
    difficultyStars: 1,
    calories: 320,
    mealType: MealTypeFilter.dessert,
    ingredientsText: ["• Hamuru için;", "• Yarım su bardağı ılık su (100 ml)", "• Yarım çay bardağı sıvı yağ (60 ml)", "• 1 yemek kaşığı şeker", "• 1 paket vanilya", "• 1,5 su bardağı un (gerekirse 1-2 kaşık daha eklenebilir)", "• İçi için;", "• Kakaolu fındık kreması"],
    requiredIngredients: [getIng('findik'), getIng('kakao'), getIng('krema'), getIng('seker'), getIng('siviyag'), getIng('un'), getIng('vanilya')],
    steps: [
        "1. Öncelikle bir pişirme kağıdı üzerine aralıklı olarak 1’er yemek kaşığı dolusu çikolata bırakalım. Bu ölçülerle 15 tane İzmir bombası hazırlayacağımız için 15 çikolata hazırlamak gerekiyor. Çikolataları bu şekilde dondurucuya kaldırıp 30-40 dk kadar donduralım. Böylelikle şekillendirirken daha rahat edersiniz. Çikolata hamurun içinde kalıp gibi durur ve hemen yayılmaz.",
        "2. İzmir bombası hamuru için öncelikle herekli malzemeleri yoğurma kabına alalım. Elimizle yoğuralım. Gerekirse hamuru toparlamak için çok az un ilave edebilirsiniz.",
        "3. Hamur toparlanınca streç film ile sarıp 20 dakika dinlendirelim.",
        "4. Sürenin sonunda hamuru dolaptan çıkarıp 15 eşit parçaya bölelim.  Her birini toparlayıp beze haline getirelim. Gayet minik bezeler olacak merak etmeyin doğru yoldasınız :)",
        "5. Bu sırada fırını 220 dereceye ısıtalım.",
        "6. Sırasıyla bezeleri açıp içerisine donmuş çikolatayı yerleştirip top haline getirelim.",
        "7. Hızlı bir şekilde tüm bezeleri açıp içlerine çikolata yerleştirip top haline getirelim.",
        "8. Hazırladığımız tatlıları pişirme kağıdı serdiğimiz tepsiye aralıklı olarak dizelim.",
        "9. İzmir bombalarını fırına verelim. Yaklaşık 6 dakika boyunca pişirelim. Pişmeyi hızlandırmak için fırının fanını da açmanızı öneririm. Üzerleri beyaz kalacak şekilde pişirelim. Hamur çok ince olduğu için hızlıca pişecektir. Benim içim rahat etmekti 1 dk daha fazla tuttum. Siz fırınınıza göre ayarlayabilirsiniz.",
        "10. İzmir bombası sıcak tüketildiğinde daha lezzetli ama dikkat edin fırından aldığınız gibi yemeyin, çikolata çok sıcak oluyor, 10 dakika kadar bekletmenizi öneririm."
    ],
    chefTip: null,
  ),
