    imageAsset: "assets/images/048.webp",
    prepTimeMinutes: 35,
    difficultyStars: 2,
    calories: 290,
    mealType: MealTypeFilter.breakfast,
    ingredientsText: ["• 3 su bardağı un (yaklaşık 330 gram)", "• 1.5 su bardağı ılık su (300 ml)", "• 1 yemek kaşığı kuru maya (veya 1 paket instant maya)", "• 1 tatlı kaşığı şeker", "• 1 çay kaşığı tuz", "• Yarım çay bardağı zeytinyağı", "• 1 su bardağı iri kıyılmış ceviz"],
    requiredIngredients: [getIng('ceviz'), getIng('seker'), getIng('tuz'), getIng('un'), getIng('zeytinyagi')],
    steps: [
        "1. Kare borcam için ılık su, maya ve şekeri alıp karıştıralım. Eğer instant maya kullanıyorsanız beklemeye gerek yok ama kuru maya ise mayanın çözülüp aktifleşmesi için 5 dakika bekletelim.",
        "2. Un ve tuzu ilave edip spatula veya kaşıkla karıştırarak hamuru toparlayalım. Yoğurmaya gerek yok, başta zor gibi gelebilir ama dakikalar içinde yapışkan bir hamur topağı elde edeceksiniz.",
        "3. Üzerini streç filmle kapatıp bir örtü örterek yarım saat mayalanmaya bırakalım.",
        "4. Yarım saatin ardından hamur kabaracak, üzerine zeytinyağı ve cevizi ekleyip ilk katlamamızı yapalım. Bunun için hamuru iki kenarını tutup ortaya doğu kapatıyoruz, alt ve üstü, sağ ve solu ortaya doğru katladık mı tamamdır. bu arada elinizi hafifçe ıslatırsanız veya üzerine eklediğiniz zeytinyağı ile yağlarsanız parmak uçlarınızı, hamur yapışmaz.",
        "5. 20 dk tekrar kabarması için bekleyip bir tur daha katlayalım.",
        "6. Son turda 20 dk daha bekleyip son kez katlayalım. Ardından hamuru un serptiğimiz tezgaha aktaralım.",
        "7. Hamurun üzerine un serpip elimizle hafif bastırarak genişletelim. Bir bıçak yardımı ile istediğimiz büyüklükte keselim. Ben 6 parçaya kestim.",
        "8. Fırın tepsisine bolca galeta unu serpelim. Yoksa pişirme kağıdı da koyabilirsiniz ama ben pide veya ekmek yaparken galeta unu kullanıyorum, kağıda gerek kalmıyor.",
        "9. Hamurları tepsiye aktaralım, 5 dk tekrar kabarması için bekletelim. Bu arada fırını 220 dereceye açarak ısıtalım. Fansız ayarda kullanıyorum, buhar yapmak isterseniz içine bir kap içinde su koyabilirsiniz.",
        "10. Ekmekleri 220 derecede 15-20 dk arası pişirelim, sonra sıcaklığı 180’e düşürüp 5 dk daha tutuyorum, içi de iyice pişsin diye. Pişme süresi fırına göre farkediyor, altını üstünü güzelce kızartınca daha çıtır oluyor.",
        "11. Fırından alınca üzerlerine temiz bir örtü örterek soğutursanız daha yumuşak olurlar. Sonrasında isterseniz arasını kesip sandviç yapabilirsiniz, isterseniz kahvaltıda servis edersiniz. Ekmekleri tost makinesinde ısıtırsanız anında tazesi gibi oluyor, bu yüzden 2-3 gün gidiyor bu ekmekler bize. Ayrıca boyutlarını kendinize göre ayarlayabilirsiniz, sandviç yapacaksanız 4’e bölmek de iyi olabilir. Şimdiden herkese afiyet olsun."
