  Recipe(
    id: "r_81",
    title: "Patates Pastası",
    emoji: "🧁",
    imageUrl: "https://i.nefisyemektarifleri.com/2013/12/patates-pastasi-yapimi-fotografi-1.jpg",
    imageAsset: "assets/images/081.webp",
