  Recipe(
    id: "r_82",
    title: "Tavuklu Spagetti",
    emoji: "🥗",
    imageUrl: "https://i.nefisyemektarifleri.com/2019/10/31/tavuklu-spagetti-1.jpg",
    imageAsset: "assets/images/082.webp",
    prepTimeMinutes: 25,
    difficultyStars: 2,
    calories: 300,
    mealType: MealTypeFilter.mainCourse,
    ingredientsText: ["• Yarım paket spagetti", "• 600 gr tavuk eti", "• kurutulmuş domates", "• 1 adet kapya biber", "• 1 çay kaşığı kadar tuz", "• 1 yemek kaşığı domates salçası", "• 1 diş sarımsak (isteğe bağlı)", "• marinesi için;", "• 3 yemek kaşığı zeytinyağı", "• 1 çay kaşığı kekik", "• 1 çay kaşığı fesleğen", "• 1 çay kaşığı pul biber", "• 1 çay kaşığı kırmızı toz biber"],
    requiredIngredients: [getIng('domates'), getIng('kapya_biber'), getIng('kekik'), getIng('makarna'), getIng('salca'), getIng('sarimsak'), getIng('tavuk'), getIng('tuz'), getIng('zeytinyagi')],
    steps: [
        "1. Öncelikle tavukları doğrayıp marine edelim.  Bunun için doğradığımız tavukları bir kaba alıp marine için gerekli malzemeleri ilave edip karıştıralım ve zaman varsa 1-2 saat dinlendirelim.",
        "2. Makarna için büyükçe bir tencerede bolca suyu kaynatalım. Yarım paket makarnayı ilave edip 9-10 dk kadar haşlayalım. Haşlama süresi makarna paketinde yazacaktır, oradan da kontrol edebilirsiniz.",
        "3. Makarna haşlanırken tavukları pişirebiliriz. Uygun bir tencereyi ocağa alıp kızdıralım. Tavukları ekleyip tavanın her tarafına dağıtalım. Tavukların birbirine yapışıp üst üste gelmemesine dikkat edelim ki pişerken sulanmasınlar. Sürekli çevirerek tavukların her tarafını pişirelim.",
        "4. Güzelce kavrulan tavuklara 1 diş sarımsak, doğranmış kapya biberler ve kurutulmuş domatesleri ekleyelim. Kurutulmuş domates için miktar vermedim, ne kadar isterseniz, kullanmasanız da sorun olmaz :)",
        "5. Biberler de kavrulunca tuzunu ve salçasını ekleyip karıştıralım. Dilerseniz mevsiminde rendelenmiş domates veya domates sosu da eklenebilir.",
        "6. Son olarak makarnamızın haşlama suyundan 1-2 kepçe kadar ilave edip sosumuzu bir iki dk kaynatalım. Makarna suyu sosun kıvamını mükemmel hale getirecektir, mutlaka kullanın.",
        "7. Haşlayıp suyunu süzdüğümüz makarnaları da ilave edip güzelce karıştıralım.",
        "8. Tavuklu spagettimiz servise hazır, şimdiden afiyet olsun. Denerseniz aşağıya siz de fotoğrafınızı eklemeyi unutmayın, sevgilerimle :)"
    ],
    chefTip: null,
  ),
