    prepTimeMinutes: 10,
    difficultyStars: 1,
    calories: 290,
    mealType: MealTypeFilter.breakfast,
    ingredientsText: ["• 2 su bardağı su", "• 5 su bardağı un", "• 1 tatlı kaşığı tuz", "• 250 gram çökelek", "• 2 adet kuru soğan", "• Yarım çay bardağı zeytinyağı", "• 1 tutam maydanoz", "• 1 tatlı kaşığı pulbiber", "• 1 çay kaşığı nane", "• 1 tutam karabiber", "• Tereyağı"],
    requiredIngredients: [getIng('karabiber'), getIng('maydanoz'), getIng('nane'), getIng('pulbiber'), getIng('sogan'), getIng('tereyagi'), getIng('tuz'), getIng('un'), getIng('zeytinyagi')],
    steps: [
        "1. Sıkmamız için; ilk önce hamuru hazırlayalım. Hamur yoğurma kabına suyu ve tuzu koyup karıştıralım. Yavaş yavaş unu ilave edip yoğuralım. Hafif ele yapışan yumuşak bir hamur olacak. Üzerini kapatıp yarım saat dinlenmeye bırakalım.",
