        "4. Dinlenen hamuru un serptiğimiz açma masasına koyup rulo yapalım. 12 eşit parçaya keselim. Ben küçük tercih ettim isteyen sayıyı azaltıp daha büyük yapabilir. Yuvarlayıp bezeler yapalım. Kurumaması için üzerini örtelim.",
        "5. Tavayı ısıtıp orta ateşte yakalım. Çok kısık olmasın. Hamurları unlayarak çevire çevire pasta tabağı kadar büyütelim. Tavaya koyalım. Kabarcıklar çıkmaya başlayınca hemen çevirelim. Tekrar kabarınca yine çevirelim.",
