        "7. İsteyen tereyağı ile yağladıktan sonra tulum peyniri veya beyaz peynir koyabilir. Soğan sevmeyenler için bende birkaç tanesini peynirli yaptım. Sıkmalar hazır. Deneyeceklere şimdiden afiyet olsun 💐🌹🌺."
