    imageAsset: "assets/images/223.webp",
    prepTimeMinutes: 12,
    difficultyStars: 1,
    calories: 300,
    mealType: MealTypeFilter.mainCourse,
    ingredientsText: ["• 1 su bardağı sıvı yağ", "• 4 adet kurusoğan", "• 4 su bardağı pirinç", "• 3 yemek kaşığı domates ve biber salçası karışık", "• 4 büyük diş rendelenmiş sarımsak", "• 1 tatlı kaşığı toz kırmızıbiber", "• 1 çay kaşığı pulbiber", "• 1/2 (yarım) çay kaşığı karabiber", "• 1 yemek kaşığı kuru nane", "• 1 tatlı kaşığı toz şeker", "• Çeyrek çay bardağı sumak ekşisi", "• 1 çay kaşığı tuz", "• 2 su bardağı sıcak su", "• 7-8 sap ince kıyım maydanoz", "• 800 gram salamura yaprak", "• 2 çay bardağı sıcak su", "• 1 yemek kaşığı salça", "• 1 yemek kaşığı nar ekşisi", "• 1 çay bardağı zeytinyağı"],
    requiredIngredients: [getIng('domates'), getIng('karabiber'), getIng('maydanoz'), getIng('nane_kurusu'), getIng('pirinc'), getIng('pulbiber'), getIng('salca'), getIng('sarimsak'), getIng('seker'), getIng('siviyag'), getIng('sogan'), getIng('tuz'), getIng('zeytinyagi')],
    steps: [
        "1. Salamura yapraklarımı suyun altında yıkayıp, bir saat sıcak suda beklemeye aldım.",
        "2. Tencereye sıvı yağını alalım. Yağ kızdığında elde yemeklik doğradığım soğanları ilave ettim üç dört dakika yumuşayıncaya kadar soteledim. Yıkayıp süzdürdüğüm pirinci içine katarak bir iki tur çevirdim.",
        "3. Üzerine havanda dövdüğüm sarımsağı salçayı ve baharatlarını katıp karıştıralım. Sumak ekşisini ve sıcak suyunu katıp üç dört dakika da bu şekilde pişirelim. Hemen suyunu çekecek.",
        "4. Ocağın üzerinden alıp ince kıyım kıydığımız maydanozları katıp karıştıralım. İç harcımız şahane oldu.",
        "5. Yapraklarımızın sap kısımlarını keselim yaprağı ikiye bölelim. Birer çay kaşığı iç harcı koyarak sıkıca rulo şeklinde saralım. Tüm yaprakları bu şekilde sararak sarmalarımızı hazırlayalım.",
        "6. Tencerenin alt kısmına havuç halkaları yerleştirelim. Üzerine kestiğimiz yaprak saplarını serpiştirelim. Sarmalarımızı tencereye yerleştirelim.",
        "7. Sosu için genişçe bir kasede tüm malzemeleri birleştirelim. Sarmanın üzerine gezdirelim. Üstüne bir kapak koyarak kapağını kapatalım. Ocağın üzerine alıp kaynamaya başlayınca ocağın en kısık halinde bir buçuk saat kontrollü pişirelim.",
        "8. Süre sonunda pişen sarmalarımızın ilk sıcağı çıktıktan sonra üzerine tepsiyi kapatarak tencereyi ters çevirelim. Üzerine limon halkaları ile sunuma hazır. Fikirlerinizi bekliyorum afiyet olsun 😋"
    ],
    chefTip: null,
  ),
