    mealType: MealTypeFilter.breakfast,
    ingredientsText: ["• 4 su bardağı un", "• 200 gram tereyağı (oda ısısında)", "• 1,5 su bardağı ılık su", "• 1 çay kaşığı kurumaya", "• 1 silme tatlı kaşığı tuz", "• 1 kâse peynir", "• 1 tutam kıyılmış maydanoz", "• 1 adet yumurta sarısı", "• 1 yemek kaşığı sıvı yağ"],
    requiredIngredients: [getIng('beyaz_peynir'), getIng('maydanoz'), getIng('siviyag'), getIng('tereyagi'), getIng('tuz'), getIng('un'), getIng('yumurta')],
    steps: [
        "1. Yoğurma kabına ılık su ve mayayı alıp karıştıralım unun önce 3 bardağını ve tuzu ekleyelim yoğurmaya başlayalım 4. Bardağı azar azar ekleyerek yumuşak bir hamur elde edelim yaklaşık 5–6 dk. özlü bir hal alınca dört eşit bezeye bölelim hafif unladığımız bir tabağa koyalım üzerini kapatalım 15 dk. Dinlendirelim.",
        "2. Dinlenen bezelerden birini alalım, bezenin altını üstünü unlayıp açmaya başlayalım bezeyi açabildiğimiz kadar ince açalım oda ısısındaki tereyağı ile her tarafını yağlayalım.",
        "3. Kenarlardan ikiye daha sonra dörde katlayarak yağlamaya devam edelim fotoğraftaki gibi☺️ yağlayıp dörde katladığımız yufka bir kenarda beklerken ikinci yufkayı da aynı şekilde açalım tereyağ ile her tarafını yağlayalım.",
        "4. Bir önceki hazırlayıp katladığımız yufkayı yağladığımız ikinci yufkanın tam ortasına alalım kenarlardan tekrar katlayarak birinci yufka içeride kalacak şekilde katlayarak kapatalım.",
        "5. Hazırladığınız bu iki yufkayı geniş bir tabağa alalım üzerine streç film ile kapalım tereyağının donması için 20-30 dk. Buzdolabına kaldıralım.",
        "6. Bu arada kalan iki bezi de aynı şekilde oklava ile açıp yağlayıp, katlayarak hazırlayalım bu iki yufkayı da aynı şekilde buzdolabına streçleyip kaldıralım.",
        "7. Önceden buzdolabına kaldırdığımız iki adet yufkayı alalım hafif unladığımız tezgahta kare şeklini bozmadan oklava ile açalım yufkayı dokuz eşit parçaya keselim.",
        "8. Kestiğimiz parçaların tam ortasına bir yemek kaşığı peynirli harçtan koyalım köşeleri ortaya getirip zarf şeklinde yapıştırarak kapatalım, yapıştırdığımız kısımlar alta gelecek şekilde yağlı kâğıt serilmiş tepsiye ters çevirerek sıralayalım.",
        "9. Buzdolabında dinlenen iki yufkayıda yine hafif unlanmış tezgahta kare şeklini bozmadan oklava ile açarak büyütelim, dokuz eşit parçaya keselim peynirli harcı koyup kapatalım tepsiye sıralayıp üzerlerine yumurta sarısı ve sıvı yağ karışımından sürelim.",
        "10. 190° ısıtılmış fırında yaklaşık 30 dk. Üzerleri kızarana kadar kontrollü pişirelim. Nefis çıtır çıtır böreklerimiz hazır ılık yada soğuk çıtır çıtır yenmek üzere 🤤🤤🤤afiyet olsun."
    ],
    chefTip: null,
