    steps: [
        "1. Öncelikle süt, nişasta, un, yumurta sarısı ve şekeri tencereye alarak çırpma teliyle güzelce karıştıralım. Çok şekerli tercih etmeyenler, şeker miktarını su bardağından 2 parmak eksik olacak şekilde alabilir.",
