        "6. Kullanacağımız kupların tabanına önce bisküvilerden yerleştirelim, daha sonra üzerine irice doğranmış ya da pirinç Antep fıstığını paylaştıralım.",
        "7. Tabanı bisküvi ve Antep fıstığı karışımıyla hazırladıktan sonra üzerine muhallebiden koyalım.",
