    requiredIngredients: [getIng('domates'), getIng('karabiber'), getIng('maydanoz'), getIng('salca'), getIng('sarimsak'), getIng('seker'), getIng('siviyag'), getIng('sogan'), getIng('tavuk'), getIng('tuz'), getIng('yogurt')],
