        "1. İlk önce Tavuk göğsümüzü yatay şekilde ince ince kesiyoruz. Tavuk bitene kadar ayni işlemi yapıyoruz.",
        "2. Daha Sonra tavuğu marine etmek için gerekli malzemeleri; yoğurt, salça, yağ, soğan ve sarımsak suyu, tuz, karabiber ve toz biberi geniş bir kapta karıştırıp üzerine yatay ve ince bir şekilde kestiğimiz tavuk göğüslerimizi ilave ediyoruz ve sosla tavuğu iyice harmanlıyoruz.",
