        "4. Tavuğumuz dinlenirken, sosumuzu hazırlayalım. Domates salçası, suyu, zeytinyağını, tuzu, karabiberi ve şekeri sos tenceremize alıp ocağa alıyoruz kıvam almadı için kısık ateşte kaynamaya bırakıyoruz.",
