        "10. Bir adet döner ekmeğimizi ortadan ikiye kesip ikisinin de üzerine biraz zeytinyağı ve toz biber karışımı yapıp sürüyoruz iyice yediriyoruz ekmeğimize.",
        "11. Ocakta kaynayan sosumuzdan da bir miktar ekmeğimize yedirip, ekmeği bir tavada dış kısmını ısıtıp biraz kızartıyoruz.",
