    mealType: MealTypeFilter.dessert,
    ingredientsText: ["• 4 adet yumurta", "• 1 su bardağı şeker", "• 1 paket vanilya", "• 3 yemek kaşığı kakao", "• 1 çay bardağı süt", "• 1 çay bardağı sıvı yağ", "• 1,5 su bardağı un", "• 1 paket kabartma tozu", "• 6 su bardağı süt", "• 5 yemek kaşığı un", "• 1 adet yumurta", "• 1 su bardağından 1 parmak eksik toz şeker", "• 1 paket vanilya", "• 300 gram labne", "• 2 paket krema", "• 120 gram sütlü veya bitter çikolata", "• Fıstık", "• Yaban mersini"],
    requiredIngredients: [getIng('cikolata'), getIng('fistik'), getIng('kabartma_tozu'), getIng('kakao'), getIng('krema'), getIng('labne'), getIng('seker'), getIng('siviyag'), getIng('sut'), getIng('un'), getIng('vanilya'), getIng('yumurta')],
    steps: [
        "1. Öncelikle kekimizi hazırlayalım. Oda sıcaklığındaki yumurtaları ve şekeri bir fiske tuz ile köpük köpük olana kadar iyice çırpalım.",
        "2. Ardından sıvı yağ ve sütü ilave edelim ve karıştıralım.",
