        "4. Önceden ısıtılmış 180° fırında 30-35 dakika pişirelim.",
        "5. Kek pişerken kremamızı hazırlayalım.",
        "6. Labne hariç tüm malzemeleri bir tencereye alalım ve ocağın altını yakmadan çırpıcı yardımıyla topak kalmayana kadar çırpalım.",
        "7. Ocağın altını yakalım ve yavaş yavaş karıştırarak kıvam alana kadar pişirelim.",
        "8. Koyulaşıp göz göz olunca ocaktan alalım ve biraz ılımasını bekleyelim (ara ara karıştırmayı ihmal etmeyelim. Kabuk bağlamasın) sonra labneyi ilave edip mikser yardımıyla pürüzsüz bir kıvama gelene kadar karıştıralım.",
        "9. Pişen keki kürdan kontrolü yaparak fırından alalım ve ilk sıcaklığı gittikten sonra bir su bardağı süt ile ıslatalım.",
        "10. Kremayı kekin üzerine eşit şekilde yayalım, düzeltelim ve bir miktar dinlendirelim.",
        "11. Son aşama olarak ganajı hazırlayalım. Kremaları sos tenceresinde ısıtalım ve çikolatayı ekleyip karıştıralım.",
        "12. Kremanın üzerine eşit şekilde yaydıktan sonra soğuması ve dinlenmesi için bir gece buzdolabında bekletelim.",
        "13. Bir gece dinlendirmek için vaktiniz yok ise sabahtan hazılayıp akşama kadar dinlenmesi de yeterli olacaktır.",
        "14. Bu şekilde dinlendiğinde krema ve ganaj çok daha güzel ve lezzetli bir kıvam alıyor.",
        "15. Servis edeceğimiz zaman ise dilediğimiz şekilde süsleme yapabiliriz. Deneyeceklere şimdiden afiyet olsun. 😋🫐."
