  Recipe(
    id: "r_480",
    title: "Sarımsaklı Peynirli Ekmek",
    emoji: "🥐",
    imageUrl: "https://i.nefisyemektarifleri.com/2025/04/13/sarimsakli-peynirli-ekmek-dominos-benzeri-focaccia-yorumu-15.jpg",
    imageAsset: "assets/images/480.webp",
    prepTimeMinutes: 80,
    difficultyStars: 3,
    calories: 290,
    mealType: MealTypeFilter.breakfast,
    ingredientsText: ["• 1.5 su bardağı ılık su", "• 0.5 su bardağı süt", "• 1 yemek kaşığı şeker", "• 0.5 yemek kaşığı tuz", "• 2 adet yumurta akı (sarıları üzerine sürmek için)", "• 1 paket instant maya", "• 0.5 su bardağı zeytinyağı", "• 4.5 su bardağı un", "• 6-7 diş sarımsak", "• Yarım su bardağından 1 parmak eksik zeytinyağı", "• 1 çay kaşığı fesleğen", "• 1 çay kaşığı kekik", "• Kaşar peyniri", "• Yumurta sarısı"],
    requiredIngredients: [getIng('kasar'), getIng('kekik'), getIng('sarimsak'), getIng('seker'), getIng('sut'), getIng('tuz'), getIng('un'), getIng('yumurta'), getIng('zeytinyagi')],
    steps: [
        "1. Ilık su, süt, maya ve şekeri karıştırıp 5 dakika bekleyelim. Ardından yumurta akı, tuz ve zeytinyağı ekleyip homojen bir karışım elde edelim. 4. 5 su bardağı unu kontrollü bir şekilde ekleyelim. Oldukça ele yapışan ve cıvık bir hamur olacak. Kesinlikle fazla un eklemeyin, focaccia ekmeğinin özelliği hamurun çok cıvık olmasıdır lütfen dikkat. Hamuru toparlayıp üstünü örtüp 40-60 dk mayalanması için bırakalım.",
        "2. Hamur mayalanırken bir kase içerisine ekmeğin üzerine süreceğimiz yağımızı hazırlayalım. Sarımsakları ezici yardımı ile ezelim, üzerine zeytinyağı ekleyip iyice karıştıralım. Ardından fesleğen ve kekik ekleyip tekrar karıştıralım. Hamur mayalandıktan sonra hamuru yağladığımız uygun boyutta bir borcam ya da tepsiye alalım. Hamur çok cıvık olduğu için elinize yapışacak sakın endişelenmeyin, bir spatula yardımıyla sıyırarak hamuru tepsiye aktarın. Parmak uçlarınızla yavaşça hamuru çekiştirerek kabın şeklini almasını sağlayın. Bu aşamada parmak uçlarınızı biraz zeytinyağı ile yağlarsanız ya da hamurun üzerine biraz zeytinyağı serpiştirirseniz çok daha kolay olacaktır.",
        "3. Hamur kabın şeklini aldıktan sonra küçük kareler halinde hamuru keselim. Üzerine yumurta sarısı sürüp yağımızı dökelim. 180 derece fırında 25-30 dakika üzeri kızarana kadar pişirelim. Sonrasında fırından alıp üzerine rendelenmiş kaşarları döküp tekrar fırına verelim. Üzeri iyice kızarana kadar yaklaşık 10 dakika daha pişirip fırından alalım.",
        "4. Bu tarif bir focaccia yorumu olduğu için zeytinyağından sakın korkmayın. İtalyan mutfağından esintiler taşıyan, oldukça lezzetli olan bu tarife bayılacaksınız. Şimdiden afiyet olsun!."
    ],
    chefTip: null,
  ),
