    ingredientsText: ["• 1 paket baklavalık hazır yufka (13 adet kullanacağız)", "• 200 gram tereyağı", "• 1 su bardağı süt", "• 2,5 dolu yemek kaşığı irmik", "• 1 paket vanilya", "• 2 su bardağı toz şeker", "• 2 su bardağı + 1 çay bardağı su", "• 4-5 damla limon suyu( ince dilimde olabilir)"],
