        "3. Son olarak limon damlalarını ekleyip 1-2 dakika daha kaynatalım ve ocaktan alalım.",
        "4. Şerbeti tamamen soğumaya bırakalım. (tatlı sıcak, şerbet soğuk olacak. ).",
        "5. Süt ve irmiği küçük bir tencereye alalım.",
        "6. Sürekli karıştırarak koyulaşana kadar pişirelim.",
