        "9. Şöbiyetin hazırlanışı; yufkaların kurumaması için altına ve üstüne temiz bez serelim.",
        "10. Tereyağını eritip köpüğünü alalım. Fırın tepsimizi hafifçe yağlayalım.",
        "11. Yufkaları tek tek aralarına tereyağı sürerek üst üste dizelim. Son kata yağ sürmeyelim.",
        "12. Yufkaları önce boydan 4 şerit olacak şekilde, ardından enine keserek kareler oluşturalım.",
