        "17. Fırından çıkan tatlıyı 4-5 dakika dinlendirelim ve soğuk şerbeti üzerine gezdirelim.",
        "18. Püf noktası tatlı sıcak, şerbet mutlaka soğuk olmalı. Yufkalar beklerken mutlaka bezle örtülü olsun.",
        "19. Üzeri kapalı saklanırsa çıtırlığı gider, açık muhafaza edelim."
