    ingredientsText: ["• 2 su bardağı ılık su", "• 1 tatlı kaşığı kuru maya", "• 1 yemek kaşığı şeker", "• 1 su bardağı irmik", "• 1,5 su bardağı un", "• Yarım çay kaşığı tuz", "• 1 tatlı kaşığı sirke", "• 2 su bardağı su", "• 2 su bardağı toz şeker", "• 3-4 damla limon", "• 1 su bardağı hafif iri dövülmüş ceviz", "• Yarım çay kaşığı tarçın"],
    requiredIngredients: [getIng('ceviz'), getIng('irmik'), getIng('limon'), getIng('seker'), getIng('tuz'), getIng('un')],
    steps: [
        "1. Bir tencereye şeker ve suyu alıp şeker eriyene kadar karıştıralım ve kaynamaya bırakalım. Kaynayınca altını kısıp şerbete birkaç damla limon suyu damlatalım ve bir 10 dakika kadar daha kaynatalım ve şerbeti soğumaya bırakalım.",
        "2. Karıştırma kabına sirke ,ılık su(parmağı yakmayacak ), maya ve şeker alıp karıştıralım. 5 dk sonra irmik, un ve tuzunu ilave edip tekrar karıştıralım (akışkan bir hamur olmalı) ve mayalanmaya bırakalım. 10 dk yeterli.",
