        "4. Kullanacağımız tavayı orta ateşte ısıtıp, hamuru tavaya dökelim. Ben dolu bir yemek kaşığı döküp üzerine yarım kaşık daha ekleyip, yayıyorum tam ortaya gelecek şekilde.",
